entries[88180] = { ["name"] = "Steinerner Greif", ["text"] = "Wirken in 2 sek. 5\nGreifen sind seit langem schon die Verbündeten der Wildhammerzwerge gewesen, die ihre edlen Reittiere in die Allianz mitbrachten. Diese kleine Figur ist meisterhaft aus Alabaster gefertigt. Ihre Klauen sind scharf genug, um Leder zu durchdringen.\nSteinerner Greif\nWird beim Aufheben gebunden" }
entries[88181] = { ["name"] = "Silberhalsring", ["text"] = "Wirken in 2 sek. 5\nDie Schmiedekunst der Zwerge ist weitbekannt. Wenn sie auch viele Waffen und Belagerungsmaschinerie produzieren, sind sie jedoch auch mit weicheren Metallen sehr geschickt. Dieses Schmuckstück wurde für eine Dame mit einem sehr dicken Hals gefertigt.\nSilberhalsring\nWird beim Aufheben gebunden" }
